import os

class ConfigError(Exception):
    pass

def get_required(name):
    value = os.environ.get(name)
    if value is None or value == "":
        raise ConfigError(f"Missing required environment variable: {name}")
    return value

def get_int(name, default):
    raw = os.environ.get(name)
    if raw is None or raw == "":
        return default
    try:
        return int(raw)
    except ValueError:
        raise ConfigError(f"Environment variable {name} must be an integer, got: {raw!r}")

class Config:
    def __init__(self):
        self.database_url = get_required("DATABASE_URL")   # required, no default
        self.batch_size = get_int("BATCH_SIZE", 1000)       # optional with default
        self.environment = os.environ.get("ENVIRONMENT", "dev")
        self.retries = get_int("MAX_RETRIES", 3)

config = Config()  # constructed at import; fails fast if misconfigured
